import type { Metadata } from "next";
import { contact, hasEmail, hasPhone } from "@/data/contact";
import type { Faq } from "@/types/content";
import { absoluteUrl, site } from "@/data/site";

/** Generated by app/opengraph-image.tsx. Repeated per page because a page-level
 *  openGraph object replaces (rather than merges with) the inherited one. */
const shareImage = { url: "/opengraph-image", width: 1200, height: 630, alt: `${site.name} — ${site.tagline}` };

export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle = false,
}: {
  title: string;
  description: string;
  path: string;
  absoluteTitle?: boolean;
}): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} · ${site.name}`;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      url: path,
      siteName: site.name,
      title: fullTitle,
      description,
      locale: site.locale,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [shareImage.url],
    },
  };
}

/** JSON-LD — only facts the documentation establishes. No ratings, reviews, prices or addresses. */
export function organizationJsonLd() {
  const contactPoint =
    hasEmail() || hasPhone()
      ? [
          {
            "@type": "ContactPoint",
            contactType: "sales",
            ...(hasEmail() ? { email: contact.email } : {}),
            ...(hasPhone() ? { telephone: contact.phone } : {}),
          },
        ]
      : undefined;
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": absoluteUrl("/#organization"),
    name: site.name,
    url: site.url,
    logo: absoluteUrl(site.logo.icon512),
    slogan: site.tagline,
    ...(site.social.length ? { sameAs: site.social.map((s) => s.href) } : {}),
    ...(contactPoint ? { contactPoint } : {}),
  };
}

export function websiteJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": absoluteUrl("/#website"),
    name: site.name,
    url: site.url,
    description: site.shortDescription,
    publisher: { "@id": absoluteUrl("/#organization") },
    inLanguage: "en",
  };
}

export function softwareJsonLd() {
  return {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    "@id": absoluteUrl("/#software"),
    name: site.name,
    applicationCategory: "BusinessApplication",
    applicationSubCategory: "Customs clearing and freight forwarding ERP",
    operatingSystem: "Web browser",
    description: site.description,
    url: site.url,
    publisher: { "@id": absoluteUrl("/#organization") },
    featureList: [
      "Multi-company workspaces with isolated data",
      "ETA sheet with documents checklist",
      "Job files linking the full shipment lifecycle",
      "14-stage customs board with dated log",
      "Transport, gate passes and partial deliveries",
      "Expense vouchers with approval",
      "Sales-tax invoices, payments, advances and statements of account",
      "Bank, cash and wallet accounts with ledgers",
      "Reports with Excel and PDF export",
      "Role-based permissions and activity log",
    ],
  };
}

export function faqJsonLd(items: Faq[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: { "@type": "Answer", text: item.answer },
    })),
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

/** Serialises JSON-LD safely for an inline <script> (escapes "<" to prevent breaking out). */
export function serializeJsonLd(data: unknown) {
  return JSON.stringify(data).replace(/</g, "\\u003c");
}
